import hashlib

def get_md5_hash(file_path):
    BLOCK_SIZE = 65536  # Size of each chunk in bytes

    with open(file_path, 'rb') as f:
        hasher = hashlib.md5()
        while True:
            data = f.read(BLOCK_SIZE)
            if not data:
                break
            hasher.update(data)
        return hasher.hexdigest()
