import sys
import serialization

class CustomDataStructure(object):
    def __init__(self, attributeTag, valueRange, priority):
        self.attributeTag = attributeTag
        self.valueRange = valueRange
        self.priority = priority

    def serialize(self):
        return serialization.serialize_class(self)

    @classmethod
    def deserialize(cls, data):
        return serialization.deserialize_class(data, cls)

def sorted(data):
    # Apply quick sort on the attribute list of each structure using Python's built-in sorted function
    return sorted(data, key=lambda x: (x.attributeTag, x.valueRange, x.priority))
```
