import random
from datetime import datetime
from lxml import etree

class ATMTransactionGenerator:
    def __init__(self):
        self.transactions = []
        self.generate_transactions()

    def generate_transactions(self):
        for i in range(20):
            transaction = {
                'account_number': random.randint(1000, 9999),
                'transaction_type': random.choice(['deposit', 'withdrawal', 'balance inquiry']),
                'amount': round(random.uniform(10, 50), 2),
                'timestamp': datetime.now().strftime(""%Y-%m-%d %H:%M:%S"")
            }
            self.transactions.append(transaction)

    def parse_xml(self, xml_file):
        root = etree.fromstring(xml_file)
        for transaction in self.transactions:
            customer_id = transaction['account_number']
            xpath = f""//customer[@id='{customer_id}']/transaction[1]""
            node = root.xpath(xpath)[0]
            if node is None:
                raise Exception(f""No matching transaction found for customer {customer_id}"")
            elif len(node) > 1:
                raise Exception(f""Multiple transactions found for customer {customer_id} with identical details"")
```
