def main():
    xml_file = ""historical_transactions.xml""
    transaction_generator = ATMTransactionGenerator()
    parsed_transactions = transaction_generator.parse_xml(xml_file)
    merged_transactions = transaction_generator.merge_transactions(parsed_transactions)
    print(""Simulated transactions:"")
    for transaction in merged_transactions:
        print(transaction)

if __name__ == ""__main__"":
    main()
