import os
import zipfile

def compress_directory(directory_path):
    if not os.path.exists(directory_path):
        print(f""Error: Directory '{directory_path}' does not exist."")
        return

    if not os.path.isdir(directory_path):
        print(f""Error: Input '{directory_path}' is not a valid directory."")
        return

    if len(os.listdir(directory_path)) == 0:
        print(""Error: Directory is empty. Nothing to compress."")
        return

    zip_file_name = f""{os.path.basename(directory_path)}.zip""

    with zipfile.ZipFile(zip_file_name, 'w', zipfile.ZIP_DEFLATED) as zipf:
        for root, dirs, files in os.walk(directory_path):
            for file in files:
                file_path = os.path.join(root, file)
                arcname = os.path.relpath(file_path, start=directory_path)
                zipf.write(file_path, arcname)
        print(f""Successfully created zip archive: {zip_file_name}"")

        delete_files = input(""Do you want to delete original files? (y/n): "")
        if delete_files.lower() == 'y':
            for root, dirs, files in os.walk(directory_path):
                for file in files:
                    file_path = os.path.join(root, file)
                    try:
                        os.remove(file_path)
                        print(f""Deleted original file: {file}"")
                    except Exception as e:
                        print(f""Error deleting {file}: {str(e)}"")

            print(""Original files deleted."")

        else:
            print(""Original files kept."")
