import flask
from flask import render_template, request, session, redirect, url_for
from flask_sqlalchemy import SQLAlchemy
from sqlalchemy import Column, String, Integer, Float
from sqlalchemy.ext.declarative import declarative_base
from flask_login import LoginManager, UserMixin, login_required, current_user
from flask_session import Session
import random

app = Flask(__name__)
app.config[""SQLALCHEMY_DATABASE_URI""] = ""sqlite:///database.db""
app.config[""SQLALCHEMY_TRACK_MODIFICATIONS""] = False
db = SQLAlchemy(app)
login_manager = LoginManager()
login_manager.init_app(app)
session = Session(app)
```

### Creating the database models

* `Book` model to store information about each book in the user's personal library
* `User` model to store information about the users
* `Quiz` model to store information about each quiz the user has taken

```
class Book(db.Model):
    id = Column(Integer, primary_key=True)
    title = Column(String)
    author = Column(String)
    publication_year = Column(Integer)
    popularity = Column(Float)

class User(db.Model, UserMixin):
    id = Column(Integer, primary_key=True)
    username = Column(String)
    email = Column(String)
    password = Column(String)

class Quiz(db.Model):
    id = Column(Integer, primary_key=True)
    user_id = Column(Integer, db.ForeignKey('user.id'))
    difficulty_level = Column(Float)
    number_of_questions = Column(Integer)
    time_limit = Column(Integer)
```

### Creating the routes and views

* `/`: the home page where users can sign in or create an account
* `/books`: a page where users can view their personal library of books and take quizzes
* `/quizzes`: a page where users can see their previous quizzes and take new ones
* `/logout`: a route to log out the user

```
@app.route('/')
def index():
    return render_template('index.html', title='Home Page')

@app.route('/books')
@login_required
def books():
    books = Book.query.all()
    return render_template('books.html', books=books, title='Books')

@app.route('/quizzes')
@login_required
def quizzes():
    quizzes = Quiz.query.filter_by(user_id=current_user.id).all()
    return render_template('quizzes.html', quizzes=quizzes, title='Quizzes')

@app.route('/logout')
def logout():
    session.pop('username', None)
    return redirect(url_for('index'))
```

### Creating the login and registration views

* `/login`: a route to allow users to sign in with their email and password
* `/register`: a route to allow new users to create an account

```
@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        email = request.form['email']
        password = request.form['password']
        user = User.query.filter_by(email=email).first()
        if user and user.check_password(password):
            login_user(user)
            return redirect(url_for('books'))
        else:
            flash('Invalid email or password')
    return render_template('login.html', title='Login')

@app.route('/register', methods=['GET', 'POST'])
def register():
    if request.method == 'POST':
        username = request.form['username']
        email = request.form['email']
        password = request.form['password']
        user = User(username=username, email=email)
        user.set_password(password)
        db.session.add(user)
        db.session.commit()
        login_user(user)
        return redirect(url_for('books'))
    return render_template('register.html', title='Register')
```

### Creating the quiz generation view

* `/quiz-generator`: a route to generate a customized arithmetic quiz with the user's desired difficulty level and number of questions

```
@app.route('/quiz-generator', methods=['GET', 'POST'])
@login_required
def quiz_generator():
    if request.method == 'POST':
        difficulty_level = float(request.form['difficulty_level'])
        number_of_questions = int(request.form['number_of_questions'])
        time_limit = int(request.form['time_limit'])
        quiz = Quiz(user_id=current_user.id, difficulty_level=difficulty_level, number_of_questions=number_of_questions, time_limit=time_limit)
        db.session.add(quiz)
        db.session.commit()
        return redirect(url_for('take-quiz', quiz_id=quiz.id))
    return render_template('quiz-generator.html', title='Quiz Generator')
```

### Creating the take quiz view

* `/take-quiz`: a route to allow users to take an arithmetic quiz and track their progress

```
@app.route('/take-quiz/<int:quiz_id>', methods=['GET', 'POST'])
@login_required
def take_quiz(quiz_id):
    if request.method == 'POST':
        quiz = Quiz.query.get(quiz_id)
        answer1 = int(request.form['answer1'])
        answer2 = int(request.form['answer2'])
        answer3 = int(request.form['answer3'])
        score = 0
        for question in quiz.questions:
            if question.answer == answer1 or question.answer == answer2 or question.answer == answer3:
                score += 1
        return render_template('take-quiz.html', quiz=quiz, title='Take Quiz')
    quiz = Quiz.query.get(quiz_id)
    return render_template('take-quiz.html', quiz=quiz, title='Take Quiz')
```

### Creating the quiz statistics view

* `/quiz-statistics`: a route to display the user's quiz statistics and ranking compared to other users

```
@app.route('/quiz-statistics', methods=['GET', 'POST'])
@login_required
def quiz_statistics():
    if request.method == 'POST':
        return render_template('quiz-statistics.html', title='Quiz Statistics')
    return render_template('quiz-statistics.html', title='Quiz Statistics')
