```
import ssl
import random
import logging
from concurrent import futures

class SecureCommunicationProtocol(object):
    def __init__(self, host, port):
        self.host = host
        self.port = port
        self.context = ssl.create_default_context()

    def establish_connection(self):
        try:
            self.socket = ssl.wrap_socket(socket.socket(socket.AF_INET, socket.SOCK_STREAM))
            self.socket.connect((self.host, self.port))
            logging.info(""Established secure connection with %s:%d"", self.host, self.port)
        except ssl.SSLError as e:
            logging.error(""Error establishing secure connection: %s"", str(e))

    def close_connection(self):
        if self.socket is not None:
            try:
                self.socket.shutdown(ssl.SHUT_RDWR)
                self.socket.close()
                logging.info(""Closed secure connection with %s:%d"", self.host, self.port)
            except ssl.SSLError as e:
                logging.error(""Error closing secure connection: %s"", str(e))
        self.socket = None

    def handle_connection(self):
        try:
            while True:
                data = self.socket.recv(1024)
                if not data:
                    break
                logging.info(""Received %d bytes from %s:%d"", len(data), self.host, self.port)
                self.decrypt_message(data)
        except ssl.SSLError as e:
            logging.error(""Error handling secure connection: %s"", str(e))

    def decrypt_message(self, data):
        try:
            message = self.context.unwrap(data, self.key)
            logging.info(""Decrypted message of length %d from %s:%d"", len(message), self.host, self.port)
            return message
        except ssl.SSLError as e:
            logging.error(""Error decrypting message: %s"", str(e))

    def encrypt_message(self, message):
        try:
            data = self.context.wrap(message, self.key)
            logging.info(""Encrypted message of length %d to %s:%d"", len(data), self.host, self.port)
            return data
        except ssl.SSLError as e:
            logging.error(""Error encrypting message: %s"", str(e))

    def send_message(self, message):
        try:
            self.socket.sendall(self.encrypt_message(message))
            logging.info(""Sent encrypted message of length %d to %s:%d"", len(data), self.host, self.port)
        except ssl.SSLError as e:
            logging.error(""Error sending encrypted message: %s"", str(e))
```
