Integrate efficient text processing techniques with strategic timing elements into a cohesive tool for effective data manipulation.",121,,"['```
import time
import os

class GamingLogAnalyzer:
    def __init__(self, filename):
        self.filename = filename
        self.last_operation = 0

    def word_count(self):
        with open(self.filename) as f:
            words = f.read().split()
            return len(words)

    def output_to_file(self, new_file):
        with open(new_file, 'w') as f:
            f.write(str(self.word_count()))

    def handle_cooldown(self):
        if time.time() - self.last_operation < 9:
            print(""Waiting for cooldown period..."")
            time.sleep(10 - (time.time() - self.last_operation))
        else:
            self.last_operation = time.time()

    def main(self, args):
        if args[1] == '-c':
            self.handle_cooldown()
            print(""Word count:"", self.word_count())
        elif args[1] == '-f':
            self.handle_cooldown()
            new_file = os.path.basename(self.filename)[:-4] + '_output.txt'
            self.output_to_file(new_file)
            print(""Output written to:"", new_file)
        else:
            print(""Invalid argument."")

if __name__ == '__main__':
    GamingLogAnalyzer('filename.txt').main(sys.argv[1:])
