// and perform data validation on the generated records.
import random
import time

def generate_records():
    records = []

    for _ in range(100):
        sri = random.randint(0, 255)
        status_flag = bool(random.getrandbits(1))

        timestamp_micros = int(time.time() * 1000000)

        if (sri > 247 and sri < 252 and status_flag == True):
            records.append([sri, status_flag, timestamp_micros])

    return records

if __name__ == ""__main__"":
