0,"Create a script to manage a library's book catalog. The program should allow users to add, remove, and update books in the catalog. It should display a menu with options for these actions and accept user input for each action. Implement error handling for invalid inputs and provide clear usage instructions when necessary.",121,,"['```
#!/usr/bin/env python

import json

class Book:
  def __init__(self, title, author, isbn):
    self.title = title
    self.author = author
    self.isbn = isbn

  def to_json(self):
    return json.dumps({""title"": self.title, ""author"": self.author, ""isbn"": self.isbn})

  @classmethod
  def from_json(cls, json_str):
    data = json.loads(json_str)
    return cls(data[""title""], data[""author""], data[""isbn""])

class BookCatalog:
  def __init__(self):
    self.books = []

  def add_book(self, book):
    self.books.append(book)

  def remove_book(self, isbn):
    for i, book in enumerate(self.books):
      if book.isbn == isbn:
        del self.books[i]

  def update_book(self, isbn, new_title=None, new_author=None, new_isbn=None):
    for i, book in enumerate(self.books):
      if book.isbn == isbn:
        if new_title:
          book.title = new_title
        if new_author:
          book.author = new_author
        if new_isbn:
          book.isbn = new_isbn

  def list_books(self):
    for i, book in enumerate(self.books):
      print(f""{i+1}. {book.to_json()}"")

if __name__ == ""__main__"":
  catalog = BookCatalog()
  while True:
    print(""-----------------------------------"")
    print(""Book Catalog Management System"")
    print(""-----------------------------------"")
    print(""[1] Add book"")
    print(""[2] Remove book"")
    print(""[3] Update book"")
    print(""[4] List books"")
    print(""[5] Quit"")
    choice = input(""Enter your choice: "")
    if choice == ""1"":
      title = input(""Enter the title of the book to add: "")
      author = input(""Enter the author of the book to add: "")
      isbn = input(""Enter the ISBN of the book to add: "")
