from flask import Flask, jsonify, request
from flask_sqlalchemy import SQLAlchemy
from flask_jwt_extended import JWTManager, get_jwt_identity

app = Flask(__name__)
app.config[""SQLALCHEMY_DATABASE_URI""] = ""postgresql://user:password@localhost/database""
db = SQLAlchemy(app)
jwt = JWTManager(app)

class Resource(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(100), nullable=False)
    description = db.Column(db.String(255), nullable=False)

@app.route(""/resources"", methods=[""GET""])
def get_resources():
    page = request.args.get(""page"", 1, type=int)
    per_page = request.args.get(""per_page"", 10, type=int)
    resources = Resource.query.order_by(Resource.id.desc()).paginate(page, per_page)
    return jsonify([resource.serialize() for resource in resources])

@app.route(""/resources"", methods=[""POST""])
def create_resource():
    data = request.get_json()
    if not data:
        return jsonify({""error"": ""No JSON data provided""}), 400
    try:
        resource = Resource(name=data[""name""], description=data[""description""])
        db.session.add(resource)
        db.session.commit()
        return jsonify(resource.serialize())
    except Exception as e:
        print(e)
        db.session.rollback()
        return jsonify({""error"": ""Failed to create resource""}), 500

@app.route(""/resources/<int:id>"", methods=[""PATCH""])
def update_resource(id):
    data = request.get_json()
    if not data:
        return jsonify({""error"": ""No JSON data provided""}), 400
    try:
        resource = Resource.query.get(id)
        if not resource:
            return jsonify({""error"": ""Resource not found""}), 404
        resource.name = data[""name""]
        resource.description = data[""description""]
        db.session.commit()
        return jsonify(resource.serialize())
    except Exception as e:
        print(e)
        db.session.rollback()
        return jsonify({""error"": ""Failed to update resource""}), 500

@app.route(""/resources/<int:id>"", methods=[""DELETE""])
def delete_resource(id):
    try:
        resource = Resource.query.get(id)
        if not resource:
            return jsonify({""error"": ""Resource not found""}), 404
        db.session.delete(resource)
        db.session.commit()
        return jsonify({""message"": ""Resource deleted successfully""}), 200
    except Exception as e:
        print(e)
        db.session.rollback()
        return jsonify({""error"": ""Failed to delete resource""}), 500

@app.route(""/protected"", methods=[""GET""])
@jwt.has_one_of_roles(""admin"")
def protected():
    return jsonify({""message"": ""Hello, admin!""}), 200

@app.errorhandler(404)
def not_found(e):
    return jsonify({""error"": ""Resource not found""}), 404

@app.errorhandler(500)
def server_error(e):
    return jsonify({""error"": ""Internal Server Error""}), 500
