import json
import hashlib
import logging

class RegistryManager:
    def __init__(self):
        self.registry = {}

    def register_factory(self, id, factory_function):
        if not callable(factory_function):
            raise ValueError(""Factory function must be callable"")
        self.registry[id] = factory_function

    def create_instance(self, id, data):
        if id not in self.registry:
            raise KeyError(f""No factory function registered for ID {id}"")
        factory_function = self.registry[id]
        return factory_function(data)

class JSONHandler:
    def __init__(self):
        self.registry_manager = RegistryManager()
        self.log = logging.getLogger(__name__)

    def to_json_string(self, obj):
        return json.dumps(obj)

    def from_json_string(self, json_str):
        return json.loads(json_str)

    def register_object_creator(self, object_type, creator_function):
        id = hashlib.md5(object_type.__name__.encode()).hexdigest()
        self.registry_manager.register_factory(id, creator_function)

    def create_object_from_json(self, object_type_id, json_str):
        obj_data = self.from_json_string(json_str)

        try:
            created_obj = self.registry_manager.create_instance(object_type_id, obj_data)
            return created_obj
        except Exception as e:
            self.log.error(f""Error creating object: {e}"")
            raise

