class RegistryManager:
    def __init__(self):
        self._registry = {}

    def add(self, id, func):
        self._registry[id] = func

    def get(self, id):
        return self._registry.get(id)

class JSONHandler:
    def __init__(self, registry_manager):
        self.registry_manager = registry_manager

    def register_creator(self, id, func):
        self.registry_manager.add(id, func)

    def convert_to_json(self, obj):
        json_str = json.dumps(obj)
        return json_str

    def convert_from_json(self, json_str):
        obj = json.loads(json_str)
        return obj

    def create_object_from_json(self, json_str):
        id = self.registry_manager.get('employee')
        creator_func = self.registry_manager.get(id)
        if creator_func:
            return creator_func(json_str)
        else:
            raise ValueError(""No creator function registered for ID '{}'"".format(id))

class Employee:
    def __init__(self, name, age):
        self.name = name
        self.age = age

def create_employee_from_dict(json_dict):
    try:
        json_str = json.dumps(json_dict)
        obj = JSONHandler().convert_from_json(json_str)
