import os
import sys
import time
from pathlib import Path

class UltraArchiveCompressor:
    def __init__(self):
        self.commands = {
            ""--help"": self.help,
            ""-s"": self.compress_size,
            ""-d"": self.decompress,
            ""-l"": self.compression_level,
            ""-f"": self.format,
            ""-o"": self.output_directory
        }
        self.input_validation = {
            ""filepath"": self.validate_filepath,
            ""option"": self.validate_option,
            ""parameter"": self.validate_parameter
        }
        self.cooldown_period = 10

    def run(self, args):
        if len(args) == 0:
            return self.help()
        command = args[0]
        if command not in self.commands:
            return self.error(""Invalid command"")
        options = args[1:]
        try:
            return self.commands[command](options)
        except Exception as e:
            return self.error(str(e))

    def help(self):
        print(""UltraArchiveCompressor v1.0"")
        print(""Usage: ultraarchivecompressor [COMMAND] [OPTIONS]... [FILEPATH]"")
        print(""Commands:"")
        print(""\t--help\t\tShow help menu"")
        print(""\t-s\t\tCompress file size"")
        print(""\t-d\t\tDecompress file"")
        print(""Options:"")
        print(""\t-l LEVEL\tSet compression level (default: 6)"")
        print(""\t-f FORMAT\tSet output format (default: zip)"")
        print(""\t-o DIRECTORY\tSet output directory (default: current directory)"")
        return True

    def compress_size(self, options):
        if len(options) == 0:
            return self.error(""Missing filepath"")
        try:
            filepath = Path(options[0])
            if not filepath.exists():
                raise Exception(""File does not exist"")
            output_directory = options[1] if len(options) > 1 else "".""
            with open(filepath, ""rb"") as f:
                data = f.read()
            return self.compress(data, output_directory)
        except Exception as e:
            return self.error(str(e))

    def decompress(self, options):
        if len(options) == 0:
            return self.error(""Missing filepath"")
        try:
            filepath = Path(options[0])
            if not filepath.exists():
                raise Exception(""File does not exist"")
            output_directory = options[1] if len(options) > 1 else "".""
            with open(filepath, ""rb"") as f:
                data = f.read()
            return self.decompress(data, output_directory)
        except Exception as e:
            return self.error(str(e))

    def compression_level(self, options):
        if len(options) == 0:
            return self.error(""Missing parameter"")
        try:
            level = int(options[0])
            if level < 1 or level > 9:
                raise Exception(""Invalid compression level"")
            return True
        except Exception as e:
            return self.error(str(e))

    def format(self, options):
        if len(options) == 0:
            return self.error(""Missing parameter"")
        try:
            format = options[0].lower()
            if format not in [""zip"", ""tar"", ""gzip""]:
                raise Exception(""Invalid output format"")
            return True
        except Exception as e:
            return self.error(str(e))

    def output_directory(self, options):
        if len(options) == 0:
            return self.error(""Missing parameter"")
        try:
            directory = Path(options[0])
            if not directory.exists():
                raise Exception(""Directory does not exist"")
            return True
        except Exception as e:
            return self.error(str(e))

    def validate_filepath(self, filepath):
        try:
            path = Path(filepath)
            if not path.exists():
                raise Exception(""File does not exist"")
            return True
        except Exception as e:
            return self.error(str(e))

    def validate_option(self, option):
        try:
            option = option.lower()
            if option not in [""-s"", ""-d""]:
                raise Exception(""Invalid option"")
            return True
        except Exception as e:
            return self.error(str(e))

    def validate_parameter(self, parameter):
        try:
            parameter = int(parameter)
            if parameter < 1 or parameter > 9:
                raise Exception(""Invalid compression level"")
            return True
        except Exception as e:
            return self.error(str(e))

    def compress(self, data, output_directory):
        try:
            with open(output_directory / ""compressed"", ""wb"") as f:
                f.write(data)
            return True
        except Exception as e:
            return self.error(str(e))

    def decompress(self, data, output_directory):
        try:
            with open(output_directory / ""decompressed"", ""wb"") as f:
                f.write(data)
            return True
        except Exception as e:
            return self.error(str(e))

    def error(self, message):
        print(""Error:"", message)
        return False
```
