import hashlib

def sha256_hash(filepath):
    """"""Compute SHA-256 hash of a file specified by its path""""""
    with open(filepath, 'rb') as f:
        hasher = hashlib.sha256()
        while True:
            chunk = f.read(8192)  # read in manageable chunks
            if not chunk:
                break
            hasher.update(chunk)
        return hasher.hexdigest()
