import xml.etree.ElementTree as ET

def get_text_from_tag(xml, tag_name, return_list=False):
    root = ET.fromstring(xml)
    elements = root.findall("".//{}"".format(tag_name))

    if not elements:
        raise Exception(""Tag '{}' not found in XML."".format(tag_name))

    text_list = []
    for element in elements:
        if len(element) > 1:
            raise Exception(""Multiple elements with tag name '{}' found."".format(tag_name))
        text_list.append(element.text)

    return text_list if return_list else """".join(text_list)
```
