0,"Create a program that implements a TaskScheduler class to manage a list of tasks. This class should allow adding tasks with associated priority levels, executing the highest priority task first, and providing an option to pause or resume task execution. Additionally, the program should include a TaskManager class that utilizes the TaskScheduler to handle task creation, execution tracking, and reporting on completed tasks. The TaskManager should be able to start and stop the scheduler based on user input and display progress updates for each executed task. Implement validation functions to ensure that tasks are correctly formatted with necessary attributes before they can be added to the scheduler. The main logic of your program should involve parsing user inputs for new tasks, scheduling them based on priority, executing tasks in sequence, and logging detailed reports of completed tasks including their start and end times.",94,,"['```
# TaskScheduler class
class TaskScheduler:
    def __init__(self):
        self.tasks = []
        self.priorities = {1: [], 2: [], 3: [], 4: []}

    # Add task with associated priority level
    def add_task(self, task, priority=1):
        if not isinstance(task, str):
            raise ValueError(""Task must be a string"")
        if priority not in [1, 2, 3, 4]:
            raise ValueError(""Priority must be between 1 and 4"")
        self.tasks.append(task)
        self.priorities[priority].append(task)

    # Execute the highest priority task first
    def execute_highest_priority_task(self):
        if len(self.priorities[1]) > 0:
            task = self.priorities[1].pop()
            print(f""Executing task {task} with priority 1"")
            return task
        elif len(self.priorities[2]) > 0:
            task = self.priorities[2].pop()
            print(f""Executing task {task} with priority 2"")
            return task
        elif len(self.priorities[3]) > 0:
            task = self.priorities[3].pop()
            print(f""Executing task {task} with priority 3"")
            return task
        elif len(self.priorities[4]) > 0:
            task = self.priorities[4].pop()
            print(f""Executing task {task} with priority 4"")
            return task

    # Pause or resume task execution based on user input
    def pause_resume_execution(self, action):
        if action == ""pause"":
            self.paused = True
        elif action == ""resume"":
            self.paused = False

# TaskManager class
class TaskManager:
    def __init__(self, scheduler):
        self.scheduler = scheduler
        self.start_time = datetime.now()
        self.end_time = None
        self.log = []

    # Start and stop the scheduler based on user input
    def start_stop(self, action):
        if action == ""start"":
            self.scheduler.execute_highest_priority_task()
        elif action == ""stop"":
            self.end_time = datetime.now()
