import hashlib
import os

def calculate_sha256(file_path, chunk_size=8192, verify_hash=False):
    if not os.path.exists(file_path):
        raise FileNotFoundError(""File does not exist"")

    with open(file_path, ""rb"") as f:
        hasher = hashlib.sha256()

        while True:
            data = f.read(chunk_size)
            if not data:
                break
            hasher.update(data)

        return hasher.hexdigest() if not verify_hash else verify_hash_match(file_path, hasher.hexdigest())

def verify_hash_match(file_path, calculated_hash):
    with open(file_path, ""rb"") as f:
        hasher = hashlib.sha256()

        while True:
            data = f.read(8192)
            if not data:
                break
            hasher.update(data)

        return calculated_hash == hasher.hexdigest()
