# Read processed output from C program and sort lines using Python list sorting methods
def sortLines(lines):
    sortedLines = sorted(lines, key=lambda x: int(x.split()[1]))
    return sortedLines

# Extract sequence numbers from last line if present
def extractSequenceNumbers(sortedLines):
    for line in reversed(sortedLines):
        match = re.search(r'\d+', line)
        if match:
            return int(match.group(0))
    return None

# Handle exceptions gracefully
try:
    # Call C program with command-line arguments and input redirection
    process = subprocess.run([""c_program"", ""-s"", ""input_file""], stdout=subprocess.PIPE)
    output = process.stdout.decode(""utf-8"")

    # Read and sort output lines
    sortedLines = sortLines(output.splitlines())

    # Extract sequence numbers from last line if present
    sequenceNumber = extractSequenceNumbers(sortedLines)
    if sequenceNumber:
        print(f""Last sequence number: {sequenceNumber}"")
except subprocess.CalledProcessError as e:
    print(""Error running C program:"", e)
