        # Generate random graph data
        vertices = []
        for i in range(num_vertices):
            v = {
                'id': f'v{i}',
                'properties': vertex_props or {},
            }
            vertices.append(v)

        edges = []
        for i in range(num_edges):
            e = {
                'src': f'v{np.random.randint(0, num_vertices)}',
                'dst': f'v{np.random.randint(0, num_vertices)}',
                'properties': edge_props or {},
            }
            edges.append(e)

        return vertices, edges

